function updateLogsPolling(){clearTimeout(state.logs.timer);state.logs.timer=null;syncLogsDrawerInert();if(state.tab!=='logs'||!app.classList.contains('inspector-open')||document.visibilityState!=='visible'||state.logs.inFlight)return;state.logs.timer=setTimeout(readLogs,LOG_POLL_MS);}
