function logsPage(name,title,rows,gap,session){const section=el('section','logs-source');section.setAttribute('aria-label',title);section.append(el('h3','logs-heading',title));if(name==='session')section.append(el('p','logs-session-id',`Session ID · ${session||'No session selected'}`));if(gap)section.append(el('p','logs-notice',name==='daemon'?'Daemon restarted or earlier daemon logs are unavailable.':'Earlier session logs are unavailable.'));if(!rows.length)section.append(el('p','logs-empty',name==='daemon'?'No daemon logs yet.':session?'No session logs yet.':'No session selected.'));for(const item of rows){const article=el('article','log-entry');article.dataset.seq=String(item.seq);const meta=el('div','log-meta');let stamp='Time unavailable';if(item.ts!=null&&Number.isFinite(Number(item.ts))){try{const date=new Date(Number(item.ts)*1000);if(Number.isFinite(date.getTime()))stamp=date.toLocaleString();}catch{}}meta.append(el('time','log-time',stamp),el('span',`log-level level-${logText(item.level).toLowerCase()}`,logText(item.level||'info')),el('span','log-kind',logText(item.kind||'event')));article.append(meta,el('p','log-summary',logText(item.summary)));section.append(article);}return section;}
function renderLogs(content,force=false){force=force||state.logs.forceRender;const signature=JSON.stringify([state.logs.daemonRows,state.logs.sessionRows,state.logs.daemonGap,state.logs.sessionGap,state.logs.error,state.session]);const current=content.querySelector('.logs-view');if(!force&&current?.dataset.signature===signature)return;const active=document.activeElement,restoreFocus=content.contains(active),selection=window.getSelection(),savedSelection=selection?.rangeCount&&current?.contains(selection.anchorNode)?{text:selection.toString(),offset:selection.anchorOffset}:null;const wrap=el('div','logs-view');wrap.dataset.signature=signature;wrap.append(logsPage('daemon','Daemon logs',state.logs.daemonRows,state.logs.daemonGap,''),logsPage('session','Session logs',state.logs.sessionRows,state.logs.sessionGap,state.session));if(state.logs.error)wrap.prepend(el('p','logs-error',state.logs.error));content.replaceChildren(wrap);content.setAttribute('aria-labelledby','tab-logs');if(restoreFocus)content.focus({preventScroll:true});if(savedSelection?.text&&selection){const textNodes=[...wrap.querySelectorAll('*')].flatMap(node=>[...node.childNodes].filter(child=>child.nodeType===Node.TEXT_NODE));const target=textNodes.find(node=>node.textContent.includes(savedSelection.text));if(target){const range=document.createRange(),start=Math.min(savedSelection.offset,target.length),end=Math.min(start+savedSelection.text.length,target.length);range.setStart(target,start);range.setEnd(target,end);selection.removeAllRanges();selection.addRange(range);}}}
async function readLogs(){if(state.logs.inFlight||state.tab!=='logs'||!app.classList.contains('inspector-open')||document.visibilityState!=='visible')return;const session=state.session||null,requestId=++state.logs.requestId,controller=new AbortController(),request={requestId,controller,session};state.logs.inFlight=request;state.logs.controller=controller;const timeout=setTimeout(()=>controller.abort(new DOMException('Logs request timed out.','TimeoutError')),LOG_TIMEOUT_MS);try{const result=await api.command({type:'LogsRead',session,daemon_cursor:state.logs.daemonCursor,session_cursor:state.logs.sessionCursor,limit:LOG_LIMIT},{signal:controller.signal});if(controller.signal.aborted||state.logs.inFlight!==request||requestId!==state.logs.requestId||session!==(state.session||null)||state.tab!=='logs')return;for(const [key,page] of [['daemon',result.daemon],['session',result.session]]){if(!page)continue;const rows=state.logs[`${key}Rows`];if(page.truncated)rows.length=0;const seen=new Set(rows.map(row=>row.seq));for(const item of page.entries||[])if(!seen.has(item.seq)){rows.push(item);seen.add(item.seq);}if(rows.length>LOG_MAX_ROWS)rows.splice(0,rows.length-LOG_MAX_ROWS);state.logs[`${key}Cursor`]=page.next_cursor??state.logs[`${key}Cursor`];state.logs[`${key}Gap`]=state.logs[`${key}Gap`]||Boolean(page.truncated);}state.logs.error='';if(state.tab==='logs')renderDetails(true);}catch(error){if(state.logs.inFlight===request&&requestId===state.logs.requestId&&session===(state.session||null)){state.logs.error=controller.signal.aborted?(controller.signal.reason?.name==='TimeoutError'?'Logs request timed out.':'Logs request was cancelled.'):error.message||'Could not load logs.';if(state.tab==='logs')renderDetails(true);}}finally{clearTimeout(timeout);if(state.logs.inFlight===request){state.logs.inFlight=null;state.logs.controller=null;}updateLogsPolling();}}
function openLogs(){if(app.classList.contains('inspector-open')&&state.tab==='logs'){closeInspector();return;}if(!app.classList.contains('inspector-open')||state.tab!=='logs')state.inspectorReturnFocus=document.activeElement;setInspectorTab('logs');app.classList.add('inspector-open');syncLogsDrawerInert();if(logsDrawerModal())$('close-inspector').focus();readLogs();}
function closeInspector(){state.panelAuto=false;storageSet(localStorage,'nexus-web-panel','closed');stopLogsPolling();app.classList.remove('inspector-open');syncLogsDrawerInert();const target=state.inspectorReturnFocus?.isConnected?state.inspectorReturnFocus:$('inspector-toggle');state.inspectorReturnFocus=null;target.focus?.({preventScroll:true});}
function resetNodes(){for(const n of nodes.values())n.remove();nodes.clear();timeline.replaceChildren();}
function renderSettings(){const level=state.detail,selected=level.value;$('settings-effective').textContent=`Effective: ${selected[0].toUpperCase()+selected.slice(1)} · ${level.source}`;$('settings-scope').textContent=state.session?`Applies to ${state.session} only. Select an option to set this session override; use “Use workspace default” to clear.`:'No active session; configure workspace and browser defaults below.';document.querySelector('[data-detail-scope="session"]').disabled=!state.session;const values={session:prefs.getSessionOverride(state.workspace,state.session),workspace:prefs.getWorkspaceDefault(state.workspace),browser:prefs.getBrowserDefault()};for(const group of ['session','workspace','browser'])document.querySelectorAll(`[data-detail-scope="${group}"] input`).forEach(r=>r.checked=r.value===(values[group]||''));}
const providers=createProviders({api,el,$});
function openSettings(){state.previousFocus=document.activeElement;$('settings-overlay').hidden=false;$('app').inert=true;syncLogsDrawerInert();renderSettings();refreshVoiceStatus();$('settings-scroll').scrollTop=0;syncSettingsNav();$('settings-dialog').focus({preventScroll:true});loadWorkspaceHealth().then(renderSettingsWorkspace);loadDefaultAgent();providers.load();}
// Mirrors the TUI Settings > Agents "New sessions start with" row (AgentDefaultSet).
async function loadDefaultAgent(note=''){const box=$('default-agent-choices'),request=++state.defaultAgentRequest;try{const result=await api.command({type:'AgentsList'});if(request!==state.defaultAgentRequest)return;const names=(result.agents||[]).filter(a=>a.name&&(!a.contexts||a.contexts.includes('root'))).map(a=>String(a.name)).slice(0,16).sort((a,b)=>(a!=='build')-(b!=='build')||a.localeCompare(b));box.replaceChildren(...names.map(name=>{const label=el('label'),input=el('input');input.type='radio';input.name='default-agent';input.value=name;input.checked=name===result.default;input.onchange=()=>saveDefaultAgent(name);label.append(input,el('span','',name));return label;}));$('default-agent-note').textContent=note;}catch(e){if(request===state.defaultAgentRequest)$('default-agent-note').textContent=`Unavailable · ${e.message}`;}}
async function saveDefaultAgent(name){const scope=document.querySelector('input[name="default-agent-scope"]:checked')?.value||'global';try{const result=await api.command({type:'AgentDefaultSet',name,scope});const path=`${scope==='global'?'~/.nexus':'.agents'}/${result.rel_path}`;await loadDefaultAgent(result.effective===result.name?`Saved to ${path}`:`Saved to ${path} · ${result.effective} still applies (project config)`);if(state.session){await refreshSelectionMetadata(state.session);renderHeader();refreshNextTurnPreview(state.session);}}catch(e){await loadDefaultAgent(`Could not save · ${e.message}`);}}
function installSettingsNav(){
  for(const link of document.querySelectorAll('.settings-nav a'))link.addEventListener('click',e=>{e.preventDefault();document.querySelector(link.getAttribute('href'))?.scrollIntoView({block:'start'});});
  $('settings-scroll').addEventListener('scroll',syncSettingsNav,{passive:true});
}
function syncSettingsNav(){
  const body=$('settings-scroll'),sections=[...body.querySelectorAll('.settings-section')],top=body.scrollTop+72;
  let current=sections[0];for(const section of sections)if(section.offsetTop<=top)current=section;
  if(body.scrollTop+body.clientHeight>=body.scrollHeight-4)current=sections.at(-1);
  for(const link of document.querySelectorAll('.settings-nav a')){const on=link.getAttribute('href')===`#${current.id}`;link.classList.toggle('selected',on);if(on)$('settings-crumb').textContent=link.textContent;}
}
function renderSettingsWorkspace(){
  const box=$('settings-workspace-info'),health=state.health;box.replaceChildren();
  const grid=el('dl','panel-grid');const add=(label,value,wide)=>{const d=el('div',wide?'wide':'');d.append(el('dt','',label),el('dd','',value));d.lastChild.title=value;grid.append(d);};
  add('Path',state.workspace,true);
  if(health?.report){const r=health.report;add('Providers',(r.providers||[]).map(p=>p.name).join(', ')||'none');add('Sessions',String(r.sessions??state.sessions.length));if(r.extensions)add('Extensions',`${r.extensions.loaded} loaded · gen ${r.extensions.generation}`);if(r.registry?.source||r.registry?.state)add('Model catalogue',[r.registry.state,r.registry.source].filter(Boolean).join(' · '));}
  box.append(grid);
  const mcp=el('section','panel-section');mcp.append(mcpSectionBody());box.append(mcp);
  if(health?.error)box.append(el('p','settings-help',`Health unavailable: ${health.error}`));
}

function closeSettings(){ $('settings-overlay').hidden=true;$('app').inert=false;syncLogsDrawerInert();state.previousFocus?.focus?.(); }
function refreshDetail(){const active=document.activeElement,restore=active&&$('inspector').contains(active)?{id:active.id,tab:active.getAttribute('role')==='tab'?active.id:null}:null;updateDetail();renderSettings();renderTimeline();renderDetails(true);if(restore){const target=restore.id?document.getElementById(restore.id):null;target?.focus({preventScroll:true});}}
function activeDetailChange(value){if(!state.session){notify('Open a session to set its detail level');return;}prefs.setSessionDetail(state.workspace,state.session,value);refreshDetail();}
function installSettingGroups(){document.querySelectorAll('[data-detail-scope]').forEach(group=>group.addEventListener('change',e=>{if(!e.target.matches('input[type=radio]'))return;const scope=group.dataset.detailScope;if(scope==='session'){activeDetailChange(e.target.value);return;}if(scope==='workspace')prefs.setWorkspaceDetail(state.workspace,e.target.value);else prefs.setBrowserDetail(e.target.value);refreshDetail();}));$('voice-enabled').onchange=async event=>{try{await writeVoiceSettings({enabled:event.target.checked});await refreshVoiceStatus();}catch(error){event.target.checked=!event.target.checked;notify(`Could not update voice setting: ${error.message}`);}};$('voice-auto-send').onchange=async event=>{try{await writeVoiceSettings({auto_send:event.target.checked});await refreshVoiceStatus();}catch(error){event.target.checked=!event.target.checked;notify(`Could not update voice setting: ${error.message}`);}};for(const [id,key,value] of [['voice-device','device',v=>v],['voice-max-seconds','max_seconds',Number]])$(id).onchange=async event=>{try{await writeVoiceSettings({[key]:value(event.target.value)});await refreshVoiceStatus();}catch(error){await refreshVoiceStatus();notify(`Could not update voice setting: ${error.message}`);}};$('voice-settings-download').onclick=()=>voiceEntry('download');$('voice-settings-remove').onclick=async()=>{try{voice.status=await api.command({type:'VoiceRemove'});renderVoiceStatus();notify('Voice model removed');}catch(error){notify(`Could not remove voice model: ${error.message}`);}};
  for(const category of ['appearance','detail','voice','agents'])$(`reset-settings-${category}`).onclick=async()=>{
    const scope=category==='agents'?(document.querySelector('input[name="default-agent-scope"]:checked')?.value||'global'):'global';
    if(!window.confirm(`Reset ${category} to default${['agents','voice'].includes(category)?` in ${scope} scope? Removed settings move to trash.`:'?'} `))return;
    try{
      if(category==='appearance'){prefs.resetTheme();state.theme='system';applyTheme();renderSettings();}
      else if(category==='detail'){prefs.resetDetail(state.workspace,state.session);refreshDetail();}
      else {await api.command({type:'SettingsReset',scope,category});if(category==='voice')await refreshVoiceStatus();else{await loadDefaultAgent('Reset to default');if(state.session){await refreshSelectionMetadata(state.session);renderHeader();refreshNextTurnPreview(state.session);}}}
    }catch(error){notify(`Could not reset settings: ${error.message}`);}
  };
  $('settings-theme').addEventListener('change',e=>{if(e.target.name!=='theme')return;prefs.setTheme(e.target.value);state.theme=e.target.value;applyTheme();});installSettingsNav();}
// Chat commands mirror ui/cli/commands.py (SPECS) name for name, with the same
// usage and wording, and run through the same host commands as the terminal
// (ui/tui/app.py:_dispatch_chat_command and ui/tui/extras.py).
const SLASH_COMMANDS=[
  ['/new','Start a new session',args=>newSessionCommand(args),'[id]',['/clear']],
  ['/sessions','List sessions and switch',args=>sessionsCommand(args),'[id]',['/session']],
  ['/model',"List models or set this session's model",args=>modelCommand(args),'[list|tier|provider/model|id]'],
  ['/effort',"Choose this session's reasoning effort",args=>effortCommand(args),'[LEVEL]',['/reasoning']],
  ['/agent',"List or select this session's root agent",args=>agentCommand(args),'[list|current|reset|NAME]'],
  ['/tools','List tools used in this transcript',()=>openInspectorTab('tools'),''],
  ['/details','Show model, context, queue, approvals, and subagents',()=>toggleInspector(),''],
  ['/context','Show assembled prompt, tools, messages, and accounting',()=>openContextDialog(),''],
  ['/reconnect','Reattach and replay missed events',()=>reconnectCommand(),''],
  ['/cancel','Cancel the active turn',()=>stopTurn(),''],
  ['/fork','Branch this session',args=>forkCommand(args),'[at_seq]'],
  ['/export','Export this session',args=>exportCurrent(['json','markdown','jsonl'].includes(args[0])?args[0]:'markdown'),'[json|markdown|jsonl]'],
  ['/help','Show this help',()=>showText('Chat commands',helpText()),''],
  ['/hotkeys','Show keyboard shortcuts',()=>showText('Keyboard shortcuts',hotkeysText()),''],
  ['/exit','Leave the chat',()=>leaveChat(),'',['/quit']],
  ['/worktrees','Review and manage child worktrees',()=>{openInspectorTab('worktrees');loadWorktrees();},''],
  ['/copy','Copy assembled context as JSON',()=>copyContext(),''],
  ['/diff','Show workspace Git diff',args=>diffCommand(args),'[--staged] [ref]'],
  ['/cost','Show token usage and available cost estimate',()=>{const u=state.view?.usage||{};notify(`Tokens: ${fmtNumber(u.input_tokens||0)} input · ${fmtNumber(u.output_tokens||0)} output`);},''],
  ['/theme','Switch between dark and light themes',args=>themeCommand(args),'[dark|light]'],
  ['/settings','Open Settings',()=>openSettings(),''],
  ['/voice','Toggle dictation or manage voice input',args=>voiceEntry(args[0]||'toggle'),'[status|download|on|off]'],
  ['/verbose','Toggle full tool output previews',()=>verboseCommand(),''],
  ['/mcp','Show MCP servers',()=>showText('MCP',mcpText()),''],
  ['/skills','Show active skills',()=>showText('Skills',skillsText()),''],
  ['/tasks','Show background agent tasks',()=>notify((state.view?.agents||[]).map(a=>`${a.id} · ${a.status} · ${a.task||a.description||''}`).join('\n')||'No background tasks'),''],
  ['/reload','Reload extensions and MCP',()=>reloadCommand(),''],
  ['/review','Ask the agent to review changes',()=>sendPrompt('Review the current workspace changes for correctness and report findings with file references.'),''],
  ['/commit','Ask the agent to commit changes',()=>sendPrompt('Review the current workspace changes, then create a commit for the completed work. Follow normal tool permissions.'),''],
  ['/archived','Browse archived sessions',()=>archivedCommand(),'',['/resume']],
];
// Aliases, as in CommandSpec.aliases: each resolves to its canonical row.
const SLASH_ALIASES={'/sesssion':'/sessions',...Object.fromEntries(SLASH_COMMANDS.flatMap(([name,,,,aliases=[]])=>aliases.map(alias=>[alias,name])))};
function slashCommand(name){const target=SLASH_ALIASES[name]||name;return SLASH_COMMANDS.find(row=>row[0]===target);}
function parseSlash(text){const m=String(text).trim().match(/^(\/\S+)(?:\s+([\s\S]*))?$/);if(!m)return null;const row=slashCommand(m[1].toLowerCase());return row?{row,args:(m[2]||'').trim().split(/\s+/).filter(Boolean)}:null;}
function openInspectorTab(tab){state.inspectorReturnFocus=document.activeElement;app.classList.add('inspector-open');setInspectorTab(tab);}
async function newSessionCommand(args){await chooseNewSessionAgent(args[0]||newId());}
// /new, Ctrl+N and + ask which root agent the session starts with; the current agent is preselected.
async function chooseNewSessionAgent(id=newId()){if(state.creatingSession)return;let rows=[];try{const result=await api.command({type:'AgentsList'});rows=(result.agents||[]).filter(a=>a&&a.name&&a.selectable!==false&&a.mode!=='subagent'&&(!a.contexts||a.contexts.includes('root'))).map(a=>({name:a.name,detail:a.description||'',agentName:a.name}));}catch(e){rows=[];}if(!rows.length){await createSession(null,id);return;}const current=String(state.agentInfo?.name||state.view?.agent_name||'').toLowerCase(),selected=Math.max(0,rows.findIndex(r=>r.name.toLowerCase()===current));chooseFromList('New session · choose an agent',rows,async row=>{if(row)await createSession(row.agentName,id);},{selected});}
async function sessionsCommand(args){if(!args[0]){showPalette();return;}const row=state.sessions.find(s=>s.id===args[0]||s.id.startsWith(args[0]));if(row)await openSession(row.id);else notify(`No session matches ${args[0]}`);}
async function modelCommand(args){if(!args[0]||args[0]==='list'){chooseModel();return;}if(!state.session)return;const session=state.session;try{invalidateNextTurnPreview(session);const selected=await api.command({type:'ModelSelect',session,ref:args[0]});if(selected.accepted===false)throw new Error('Model selection was rejected');state.selectedModel={provider:selected.provider||'',model:selected.model||args[0],tier:selected.tier||''};await refreshSelectionMetadata(session);renderHeader();refreshNextTurnPreview(session);}catch(e){notify(`Command failed · ${e.message}`);refreshNextTurnPreview(session);}}
async function agentCommand(args){const arg=args[0];if(!arg||arg==='list'){chooseAgent();return;}if(!state.session)return;if(arg==='current'){notify(`Agent · ${titleCase(state.agentInfo?.name)||'default'}`);return;}const session=state.session;try{invalidateNextTurnPreview(session);const result=arg==='reset'?await api.command({type:'AgentReset',session}):await api.command({type:'AgentSelect',session,name:arg});if(result.apply_next_turn===false)throw new Error('Agent selection did not apply to the next turn');await refreshSelectionMetadata(session);renderHeader();refreshNextTurnPreview(session);}catch(e){notify(`Command failed · ${e.message}`);refreshNextTurnPreview(session);}}
async function effortCommand(args){if(!state.session){notify('Start or open a session to choose its reasoning effort');return;}const session=state.session;try{const current=await fetchSelectionMetadata(session);if(state.session!==session)return;const levels=Array.isArray(current.supported_levels)?current.supported_levels:[];if(!levels.length){notify('Reasoning effort unavailable for this model');return;}if(args[0]){const level=args[0].toLowerCase();if(levels.includes(level))await selectEffort(session,level);else notify(`Use /effort ${levels.join('|')}`);return;}chooseFromList('Choose reasoning effort',levels.map(level=>({name:level,detail:level===current.reasoning_effort?'Current · applies next turn':'Applies next turn',level})),(row,_unused,selected)=>selectEffort(selected,row.level),{session});const index=levels.indexOf(current.reasoning_effort);if(index>=0){state.choiceSelected=index;renderPalette('');}}catch(e){if(state.session===session)notify(`Could not change reasoning effort: ${e.message}`);}}
async function selectEffort(session,effort){if(!session||session!==state.session||state.effortPending)return;state.effortPending=true;try{invalidateNextTurnPreview(session);const result=await api.command({type:'ReasoningEffortSelect',session,effort});if(state.session!==session)return;if(result.accepted===false)throw new Error('Reasoning effort selection was rejected');await refreshSelectionMetadata(session);renderHeader();refreshNextTurnPreview(session);}catch(e){if(state.session===session){refreshNextTurnPreview(session);notify(`Could not change reasoning effort: ${e.message}`);}}finally{state.effortPending=false;}}
async function reconnectCommand(){if(!state.session)return;await connectSession(state.session);notify('Reconnected');}
async function forkCommand(args){if(!state.session)return;const at=/^\d+$/.test(args[0]||'')?Number(args[0]):null;try{const result=await api.command({type:'SessionFork',session:state.session,at_seq:at});const id=typeof result.session==='string'?result.session:result.session?.id;await refreshSessions();if(id)await openSession(id);}catch(e){notify(`Command failed · ${e.message}`);}}
async function diffCommand(args){const refs=args.filter(arg=>arg!=='--staged');if(refs.length>1){notify('Use /diff [--staged] [ref]');return;}try{const diff=await api.command({type:'GitDiff',staged:args.includes('--staged'),ref:refs[0]||''});showText('Git diff',(diff.patch||'No changes')+(diff.truncated?'\n\n[diff truncated]':''),{diff:true});}catch(e){notify(`Command failed · ${e.message}`);}}
function themeCommand(args){const requested=['dark','light'].includes(args[0])?args[0]:(document.documentElement.style.colorScheme==='light'?'dark':'light');state.theme=requested;prefs.setTheme(requested);applyTheme();}
function verboseCommand(){notify('Tool details open in a modal when selected');}
async function copyContext(){const result=state.header?.session===state.session?state.header.result:null;if(!result){notify('Context is unavailable');return;}try{await navigator.clipboard.writeText(JSON.stringify(result,null,2));notify('Copied context JSON');}catch{notify('Clipboard is unavailable in this browser');}}
async function reloadCommand(){try{const result=await api.command({type:'ExtensionsReload',trigger:'chat'});notify([`Extensions generation ${result.generation??'?'}`,result.changed?'changed':'unchanged',result.loaded?.length?`loaded ${result.loaded.join(', ')}`:'',result.failed?.length?`${result.failed.length} failed`:''].filter(Boolean).join(' · ').slice(0,240));refreshNextTurnPreview();}catch(e){notify(`Command failed · ${e.message}`);}}
function sendPrompt(text){input.value=text;sendMessage();}
function leaveChat(){saveDraft();history.pushState({},'','/');dispatchEvent(new PopStateEvent('popstate'));}
async function archivedCommand(){await refreshArchived();const rows=state.archived.map(s=>({name:s.title||'Untitled session',detail:`${s.id} · ${relativeTime(s.last_activity)}`,id:s.id}));chooseFromList('Archived sessions',rows,async row=>{try{await api.command({type:'SessionUnarchive',session:row.id});await refreshSessions();await refreshArchived();await openSession(row.id);}catch(e){notify(`Command failed · ${e.message}`);}});}
function helpText(){const label=([name,,,usage,aliases=[]])=>`${[name,...aliases].join(', ')} ${usage}`.trim(),width=Math.max(...SLASH_COMMANDS.map(row=>label(row).length));return SLASH_COMMANDS.map(row=>`${label(row).padEnd(width+2)}${row[1]}`).join('\n');}
function mcpText(){const r=state.header?.result;if(!r)return 'Context unavailable';const servers=Array.isArray(r.mcp_servers)?r.mcp_servers:[];return servers.length?servers.map(row=>`${row.name} · ${row.status||''}\n  ${(row.tools||[]).join(', ')}`).join('\n'):(r.mcp_index||'(none)');}
function skillsText(){const r=state.header?.result;if(!r)return 'Context unavailable';const rows=(r.skills_index||[]).filter(row=>row&&row.included!==false);return rows.map(row=>`${row.name||'?'} · ${row.scope||''} · ${row.origin||''}\n${row.description||''}`).join('\n\n')||'(none)';}
// ui/tui/app.py:SHORTCUTS, key for key. On macOS the browser keeps ⌘, so Control is free.
const SHORTCUTS=[['Enter','Send message'],['Shift+Enter','Insert newline'],['Ctrl+P','Commands (⌘K also works)'],['Ctrl+N','New session'],['Ctrl+O','List sessions'],['Ctrl+F','Fork session'],['Ctrl+G','Open the root-agent picker'],['Ctrl+B','Toggle the sessions sidebar'],['Ctrl+L','Toggle the details sidebar'],['Ctrl+S','Settings'],['Ctrl+I','Inspect context preview and usage'],['Ctrl+T','Cycle root reasoning effort'],['Ctrl+E','Toggle the Logs drawer'],['Ctrl+Space','Dictate (voice input)'],['Ctrl+X M','Choose model'],['Ctrl+X V','Dictate; any key stops, Esc discards'],['Ctrl+X N','New session'],['Ctrl+X O','List sessions'],['Ctrl+X F','Fork session'],['Ctrl+X G','Open the root-agent picker'],['Ctrl+X B','Toggle the sessions sidebar'],['Ctrl+X L','Toggle the details sidebar'],['Ctrl+X S','Settings'],['Ctrl+X I','Inspect context preview and usage'],['Ctrl+X E','Toggle the Logs drawer'],['Ctrl+X T','Cycle root reasoning effort'],['Ctrl+X R','Reconnect'],['Ctrl+X ?','Show keyboard shortcuts'],['A','Open the root-agent picker (outside the editor)'],['Shift+Tab','Cycle root agent (in the editor)'],['Ctrl+C','Cancel the active turn'],['Ctrl+R','Reconnect'],['Escape','Close the top-most panel or dialog']];
