async function cycleAgent(){if(!state.session||activeTurn())return;try{const result=await api.command({type:'AgentsList'}),names=(result.agents||[]).filter(row=>row&&row.name&&row.selectable!==false&&row.mode!=='subagent').map(row=>String(row.name));if(!names.length)return;const current=String(state.agentInfo?.name||'').toLowerCase(),index=names.findIndex(name=>name.toLowerCase()===current);await agentCommand([names[(index+1)%names.length]]);}catch(e){notify(`Command failed · ${e.message}`);}}
function showText(title,body,{diff=false}={}){const overlay=$('text-overlay');state.textReturnFocus=document.activeElement;$('text-title').textContent=title;const pre=$('text-body');pre.replaceChildren();if(diff){for(const line of String(body).split('\n')){const row=el('span',line.startsWith('+')&&!line.startsWith('+++')?'add':line.startsWith('-')&&!line.startsWith('---')?'del':line.startsWith('@@')?'hunk':'',`${line}\n`);pre.append(row);}}else pre.textContent=body;overlay.hidden=false;app.inert=true;$('text-dialog').focus({preventScroll:true});}
