document.addEventListener('keydown',event=>{if($('text-overlay').hidden)return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();closeText();}else if(event.key==='Tab'){const focusable=[...$('text-overlay').querySelectorAll('button:not([hidden])')];if(!focusable.length){event.preventDefault();return;}const index=focusable.indexOf(document.activeElement),next=(index+(event.shiftKey?-1:1)+focusable.length)%focusable.length;event.preventDefault();focusable[next].focus();}},true);
const slash={open:false,rows:[],selected:0};
function slashQuery(){const m=input.value.match(/^\/(\S*)$/);return m?m[1].toLowerCase():null;}
function renderSlash(){
  const query=slashQuery(),menu=$('slash-menu');
  if(query===null||input.disabled){closeSlash();return;}
  slash.rows=SLASH_COMMANDS.filter(([name,summary,,,aliases=[]])=>[name,...aliases].some(n=>n.slice(1).startsWith(query))||summary.toLowerCase().includes(query));
  slash.selected=Math.min(slash.selected,Math.max(0,slash.rows.length-1));slash.open=true;menu.hidden=false;menu.replaceChildren();
  slash.rows.forEach(([name,summary,,usage,aliases],i)=>{const b=el('button',`slash-item ${i===slash.selected?'selected':''}`);b.type='button';b.id=`slash-${i}`;b.setAttribute('role','option');b.setAttribute('aria-selected',String(i===slash.selected));b.tabIndex=-1;b.append(el('span','',usage?`${name} ${usage}`:name),el('span','',aliases?.length?`${summary} · also ${aliases.join(', ')}`:summary));b.onmousedown=e=>e.preventDefault();b.onclick=()=>runSlash(i);menu.append(b);});
  if(!slash.rows.length)menu.append(el('div','slash-empty','No matching command'));
  input.setAttribute('aria-activedescendant',slash.rows.length?`slash-${slash.selected}`:'');
  menu.querySelector('.selected')?.scrollIntoView({block:'nearest'});
}
function closeSlash(){slash.open=false;slash.selected=0;$('slash-menu').hidden=true;input.removeAttribute('aria-activedescendant');}
function runSlash(i,args=[]){const row=slash.rows[i];if(!row)return;input.value='';saveDraft();closeSlash();row[2](args);}
input.addEventListener('input',()=>{slash.selected=0;renderSlash();});
input.addEventListener('blur',()=>setTimeout(()=>{if(document.activeElement!==input)closeSlash();},120));
input.addEventListener('keydown',e=>{
  if(!slash.open||e.isComposing||e.keyCode===229)return;
  const n=slash.rows.length;
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){if(!n)return;e.preventDefault();e.stopImmediatePropagation();slash.selected=(slash.selected+(e.key==='ArrowDown'?1:-1)+n)%n;renderSlash();}
  else if((e.key==='Enter'&&!e.shiftKey)||e.key==='Tab'){if(!n)return;e.preventDefault();e.stopImmediatePropagation();runSlash(slash.selected);}
  else if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeSlash();}
},true);
