async function fetchSelectionMetadata(session){return api.command({type:'AgentCurrent',session});}
async function refreshSelectionMetadata(session=state.session){if(!session)return false;const request=++state.metadataRequest;try{const info=await fetchSelectionMetadata(session);if(request!==state.metadataRequest||state.session!==session||info.session&&info.session!==session)return false;state.agentInfo=info;renderHeader();return true;}catch{return false;}}
