function chooseFromList(title,rows,select,{mode='',session=state.session,currentEffort=null,currentModel=null,selected=0}={}){if(!rows.length){notify(`No ${title.toLowerCase()} options are currently available`);return;}saveDraft();state.previousFocus=document.activeElement;state.choiceRows=rows;state.choiceResolve=select;state.choiceMode=mode;state.choiceSession=session;state.choiceSelected=selected;state.choiceEffort=null;state.choiceEfforts=mode==='model'?Object.fromEntries(rows.map(row=>[row.reference,null])):{};state.choiceCurrentEffort=currentEffort;if(mode==='model'){const model=currentModel||state.selectedModel||state.agentInfo||state.view?.model||{},row=rows.find(candidate=>candidate.provider===model.provider&&candidate.model===model.model);if(row){state.choiceSelected=rows.indexOf(row);state.choiceEfforts[row.reference]=Array.isArray(row.supported_efforts)&&row.supported_efforts.includes(currentEffort)?currentEffort:null;}}$('app').inert=true;setOverlay(true);syncLogsDrawerInert();$('palette-title').textContent=title;$('palette-input').value='';$('palette-input').placeholder='Search…';$('palette-input').setAttribute('aria-label',title);renderPalette('');$('palette-input').focus();}
